var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/SubGames/Packaging.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var roots = scene.GetRootGameObjects();
Sim.SubGames.Packaging.PackagingFeedback fb = null;
UnityEngine.Transform content = null;
foreach (var r in roots) {
    if (fb == null) fb = r.GetComponentInChildren<Sim.SubGames.Packaging.PackagingFeedback>(true);
    foreach (var t in r.GetComponentsInChildren<UnityEngine.Transform>(true)) {
        if (t.name == "Content") {
            var canvas = t.GetComponentInParent<UnityEngine.Canvas>();
            if (canvas != null) { content = t; break; }
        }
    }
    if (content != null) break;
}
string FullPath(UnityEngine.Transform tr) {
    string p = tr.name; var t = tr;
    while (t.parent != null) { t = t.parent; p = t.name + "/" + p; }
    return p;
}
if (fb != null) Debug.Log("Feedback: " + FullPath(fb.transform) + " iid=" + fb.GetInstanceID());
if (content != null) Debug.Log("Content: " + FullPath(content) + " iid=" + content.GetInstanceID());
